fn matvecRows(g: *const Gguf, t: *const Tensor, x: []const f32, out: []f32, r0: usize, r1: usize) void {
    const cols: usize = @intCast(t.ne[0]);
    const nblk = cols / 128;
    const raw = g.tensorData(t);
    var blk: [128]f32 = undefined;
    for (r0..r1) |r| {
        const base = r * nblk * 28;
        var vacc: @Vector(8, f32) = @splat(0.0);
        for (0..nblk) |b| {
            ggufmod.dequantBlock(raw[base + b * 28 ..][0..28], &blk);
            const xs = x[b * 128 ..][0..128];
            var k: usize = 0;
            while (k < 128) : (k += 8) {
                const bv: @Vector(8, f32) = blk[k..][0..8].*;
                const xv: @Vector(8, f32) = xs[k..][0..8].*;
                vacc += bv * xv;
            }
        }
        out[r] = @reduce(.Add, vacc);
    }
}

const MVJob = struct {
    g: *const Gguf,
    t: *const Tensor,
    x: []const f32,
    out: []f32,
    r0: usize,
    r1: usize,
    fn run(job: MVJob) void {
        matvecRows(job.g, job.t, job.x, job.out, job.r0, job.r1);
    }
};

const n_workers: usize = 8;

/// out[o] = sum_i W[o][i] * x[i] for a PTQ1_0 weight, using the stored ternary weights.
fn matvecPtq(g: *const Gguf, t: *const Tensor, x: []const f32, out: []f32) void {
    const rows: usize = @intCast(t.ne[1]);
    if (rows < 64) {
        matvecRows(g, t, x, out, 0, rows);
        return;
    }
    const want = @min(n_workers, rows / 64);
    var threads: [n_workers]?std.Thread = .{null} ** n_workers;
    const chunk = (rows + want - 1) / want;
    var spawned: usize = 0;
    var w: usize = 1;
    while (w < want) : (w += 1) {
        const r0 = @min(rows, w * chunk);
        const r1 = @min(rows, (w + 1) * chunk);
        if (r0 >= r1) break;
        threads[w] = std.Thread.spawn(.{}, MVJob.run, .{MVJob{ .g = g, .t = t, .x = x, .out = out, .r0 = r0, .r1 = r1 }}) catch null;
        if (threads[w] != null) spawned += 1;
    }
    matvecRows(g, t, x, out, 0, @min(rows, chunk));
    for (threads) |mt| {
        if (mt) |th| th.join();
    }
    _ = spawned;
}

