const n_workers: usize = 16;

/// out[o] = sum_i W[o][i] * x[i] for a PTQ1_0 weight, using the stored ternary weights.
fn matvecPtq(g: *const Gguf, t: *const Tensor, x: []const f32, out: []f32) void {
    const rows: usize = @intCast(t.ne[1]);
    if (rows < 64) {
        matvecRows(g, t, x, out, 0, rows);
        return;
    }
    const want = @min(n_workers, rows / 64);
    var threads: [n_workers]?std.Thread = @splat(null);
    const chunk = (rows + want - 1) / want;
    var w: usize = 1;
    while (w < want) : (w += 1) {
        const r0 = @min(rows, w * chunk);
        const r1 = @min(rows, (w + 1) * chunk);
        if (r0 >= r1) break;
        threads[w] = std.Thread.spawn(.{}, MVJob.run, .{MVJob{ .g = g, .t = t, .x = x, .out = out, .r0 = r0, .r1 = r1 }}) catch null;
    }
    matvecRows(g, t, x, out, 0, @min(rows, chunk));
    for (threads) |mt| {
        if (mt) |th| th.join();
    }
}

