const Pool = struct {
    threads: []std.Thread,
    mutex: std.Thread.Mutex = .{},
    cond: std.Thread.Condition = .{},
    done: std.Thread.Condition = .{},
    job: ?MVJob = null,
    gen: u64 = 0,
    active: usize = 0,
    stop: bool = false,
    nworkers: usize,

    fn worker(self: *Pool, idx: usize) void {
        var seen: u64 = 0;
        while (true) {
            self.mutex.lock();
            while (!self.stop and self.gen == seen) self.cond.wait(&self.mutex);
            if (self.stop) {
                self.mutex.unlock();
                return;
            }
            seen = self.gen;
            const job = self.job.?;
            self.mutex.unlock();
            const total = self.nworkers + 1;
            const chunk = (job.rows + total - 1) / total;
            const r0 = @min(job.rows, (idx + 1) * chunk);
            const r1 = @min(job.rows, (idx + 2) * chunk);
            if (r0 < r1) matvecRows(job.g, job.t, job.x, job.out, r0, r1);
            self.mutex.lock();
            self.active -= 1;
            if (self.active == 0) self.done.signal();
            self.mutex.unlock();
        }
    }

    fn dispatch(self: *Pool, job: MVJob) void {
        if (job.rows < 128) {
            matvecRows(job.g, job.t, job.x, job.out, job.r0, job.r1);
            return;
        }
        self.mutex.lock();
        self.job = job;
        self.active = self.nworkers;
        self.gen += 1;
        self.cond.broadcast();
        self.mutex.unlock();
        const total = self.nworkers + 1;
        const chunk = (job.rows + total - 1) / total;
        matvecRows(job.g, job.t, job.x, job.out, 0, @min(job.rows, chunk));
        self.mutex.lock();
        while (self.active != 0) self.done.wait(&self.mutex);
        self.mutex.unlock();
    }

    fn create(alloc: std.mem.Allocator) !*Pool {
        const p = try alloc.create(Pool);
        p.* = .{ .threads = &.{}, .nworkers = 0 };
        const n = @min(@as(usize, 12), (std.Thread.getCpuCount() catch 4) -| 1);
        if (n == 0) return p;
        p.threads = try alloc.alloc(std.Thread, n);
        p.nworkers = n;
        var i: usize = 0;
        while (i < n) : (i += 1) {
            p.threads[i] = std.Thread.spawn(.{}, Pool.worker, .{ p, i }) catch {
                p.nworkers = i;
                break;
            };
        }
        return p;
    }

    fn destroy(self: *Pool, alloc: std.mem.Allocator) void {
        self.mutex.lock();
        self.stop = true;
        self.cond.broadcast();
        self.mutex.unlock();
        for (self.threads[0..self.nworkers]) |th| th.join();
        if (self.threads.len > 0) alloc.free(self.threads);
        alloc.destroy(self);
    }
};

var g_pool: ?*Pool = null;

