    const job = MVJob{ .g = g, .t = t, .x = x, .out = out, .r0 = 0, .r1 = rows, .rows = rows };
    if (g_pool) |p| {
        p.dispatch(job);
    } else {
        matvecRows(g, t, x, out, 0, rows);
    }
}

