API is workable. Plan:

1. Shader `matvec.comp` (GLSL) computing out[row] = dot(W row, x), PTQ1_0 blocks. Push constants: w_byte_offset (uint), rows? not needed, cols (uint). Weight buffer bound as storage buffer of uint; we need byte access. Bind buffer as `uint w[]` and use byte extraction. Since each tensor gets its OWN buffer (upload tensor data only), offset=0; push constants: cols (uint). But descriptors need buffer size limits: maxStorageBufferRange (likely 4GB or 2GB? our tensors ≤ 139MB fine).

2. Dispatch one invocation per row: local_size_x=64.
GLSL:
```
#version 450
layout(local_size_x = 64) in;
layout(std430, binding=0) readonly buffer W { uint w[]; };
layout(std430, binding=1) readonly buffer X { float x[]; };
layout(std430, binding=2) writeonly buffer O { float o[]; };
layout(push_constant) uniform P { uint cols; } pc;
uint byteAt(uint i) { return (w[i>>2] >> ((i & 3u)*8u)) & 0xFFu; }
int trit(uint byteIdx, uint dgt) {
    uint b = byteAt(byteIdx);
    uint v = (b * pow3[dgt]) & 0xFFu;   // need table
    return int((v * 3u) >> 8u) - 1;
}
void main(){
  uint row = gl_GlobalInvocationID.x;
  uint cols = pc.cols;
  uint nblk = cols/128u;
  float acc = 0.0;
  for (uint b=0;b<nblk;b++){
    uint base = (row*nblk + b)*28u;
    uint lo = byteAt(base+26u); uint hi=byteAt(base+27u);
    float d = unpackHalf2x16(lo | (hi<<8u)).x;
