fn uploadWeightsToVk(m: *Model) void {
    const alloc = m.alloc;
    const p = alloc.create(vkmod.Vk) catch return;
    p.* = vkmod.Vk.init(alloc) catch {
        alloc.destroy(p);
        return;
    };
    const data = m.g.data;
    const start: usize = @intCast(@min(m.g.data_offset, data.len));
    const chunk: usize = 64 << 20;
    var list = std.ArrayList(vkmod.Buffer).empty;
    var off: usize = start;
    while (off < data.len) : (off += chunk) {
        const end = @min(data.len, off + chunk);
        const b = p.uploadDeviceLocal(data[off..end]) catch break;
        list.append(alloc, b) catch break;
    }
    m.vk_bufs = list.toOwnedSlice(alloc) catch &.{};
    m.vk = p;
}

